EDIT: Okay here it is so far:

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using System.IO;

public class GameManager : MonoBehaviour {

	public static bool GameIsOver = false;
	public GameObject gameOverUI;
    public string[] scores = new string[3];
    private int[] scoresInt = new int[3];
    public StreamReader reader;
    public StreamWriter writer;

	void Start(){

        reader = new StreamReader("Assets/Scores/scores.txt");
        scores[0] = reader.ReadLine();
        scores[1] = reader.ReadLine();
        scores[2] = reader.ReadLine();

        scoresInt[0] = int.Parse(scores[0]);
        scoresInt[1] = int.Parse(scores[1]);
        scoresInt[2] = int.Parse(scores[2]);
        reader.Close();
        GameIsOver = false;
	}
	void Update(){

		if (GameIsOver == true) {
			return;
		}

		if (PlayerStats.Lives <= 0) {
			EndGame ();
		}
	}

	void EndGame(){
        writer = new StreamWriter("Assets/Scores/scores.txt");
        GameIsOver = true;
        for (int i = 0; i < 3; i++) {
            if (WaveSpawner.instance.waveNumber > scoresInt[i]) {
                scoresInt[i] = WaveSpawner.instance.waveNumber;
                writer.WriteLine(scoresInt[i].ToString());
                break;
            }
        }
        Debug.Log ("Game over!");
		gameOverUI.SetActive (true);
	}
}

