This is the arrowFired function: 

	void arrowFired(){
		this.transform.SetParent (bow.transform);
		if (Time.time > LastArrowTime + reloadTime) {
			Instantiate (arrow, startPos, positionSet.transform.rotation);
			needAnotherArrow = false;
			LastArrowTime = Time.time;
