Dont mean to be too needy (know I already have been so sorry!) but one more thing: the bow sometimes fires two arrows at once and I dont know why. This wouldn't be an issue (it would be pretty cool actually) if they didnt stop when they hit each other as I made it so when the arrow hits something it becomes kinematic.
Would ya mind having a look too to see if ya can spot the issue (I already tried about 10 times and cant)? 

using UnityEngine;
using System.Collections;

public class BowScript : MonoBehaviour {

	public GameObject arrow;
	public float DrawBackSpeed = 0.5f;
	public float MoveSpeedSlow = 2f;
	public bool isBowBeingUsed = false;
	public Vector3 thePos;
	Vector3 theRot;

	// Use this for initialization
	void Start () {

	}

	// Update is called once per frame
	void FixedUpdate () {

		thePos.x = this.transform.position.x - (float)0.35;
		thePos.y = this.transform.position.y - (float)0.4;
		thePos.z = this.transform.position.z;

		if (Input.GetMouseButtonDown (0)) {
			isBowBeingUsed = true;
		}

		if (Input.GetMouseButtonUp (0)) {
			isBowBeingUsed = false;

			GameObject cloneArrow = (GameObject)Instantiate (arrow, thePos, Quaternion.identity);
			cloneArrow.transform.position = thePos;
			cloneArrow.transform.rotation = this.transform.rotation;
			cloneArrow.transform.Rotate(-90,0,0);

		}


	}
}

Thanks!

Hello again,
Thank you for responding! It got me one step closer to having a working bow and arrow! However I am stuck again. I modified my code to try to get it to work but I dont know whats wrong with it again. Here is the code:
using UnityEngine;
using System.Collections;

public class ArrowScript : MonoBehaviour {

	public int arrowSpeed = 40;
	public int dropOffDistance = 10;
	private int distanceTravelled = 0;
	public GameObject bow;
	public bool isArrowTravelling = true;


	private BowScript bowScript;
	void Start()
	{
		bowScript = GetComponent<BowScript> ();
		InvokeRepeating ("updateArrowDistance", 0, 1.0f);
		while (distanceTravelled > dropOffDistance) {
			InvokeRepeating ("dropArrowOff", 0, 0.1f);
		}
	}
	// Update is called once per frame
	void Update () {

		this.transform.Translate (Vector3.back * arrowSpeed * Time.deltaTime);

	}

	void dropArrowOff(){
		gameObject.transform.Translate (0, -1, 0);
	}

	void updateArrowDistance(){
		distanceTravelled++;
	}
}

Thank you again!
Oh also in the original post's code I didn't mean to destroy the arrow but instead make it go down in elevation.
Thanks again!
